// Receives text from Extract PDF node + metadata from Prep Binary
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json || {};
  const binary = item.binary || {};

  // Get extracted text from Extract PDF node output
  const rawText = data.text || '';
  const filename = data.filename_original || '';
  const mimeType = data.mime_type || '';

  // Get metadata passed through from Prep Binary
  let prepData = {};
  try {
    prepData = $('Prep Binary').first().json || {};
  } catch (e) { prepData = data; }

  // Get doc_type hint from WF1 (if available)
  let docTypeHint = '';
  try {
    docTypeHint = $('Doc Processor Webhook').first().json.body.docTypeHint || '';
  } catch (e) { /* no hint available */ }

  // Check for scanned/empty PDF
  if (!rawText.trim()) {
    results.push({
      json: {
        from: prepData.from || '',
        fromName: prepData.fromName || '',
        subject: prepData.subject || '',
        received_at: prepData.received_at || new Date().toISOString(),
        received_at_pst: prepData.received_at_pst || '',
        messageId: prepData.messageId || '',
        threadId: prepData.threadId || '',
        raw_text: '',
        doc_type: 'unknown',
        is_scanned: true,
        filename_original: prepData.filename_original || filename,
        mime_type: prepData.mime_type || mimeType,
        page_count: 0,
        extraction_error: 'Empty text extraction \u2014 possibly scanned PDF or password-protected'
      },
      binary: binary
    });
    continue;
  }

  // Classify doc_type — ORDER MATTERS: most specific first
  const lowerFilename = (prepData.filename_original || filename).toLowerCase();
  const lowerText = rawText.toLowerCase().substring(0, 3000);
  const lowerSubject = (prepData.subject || '').toLowerCase();
  let docType = 'unknown';

  // 1. BOD Meeting: agenda+minutes, not just "board" (too broad)
  if (lowerFilename.match(/agenda|minutes|bod[-_ ]|board[-_ ]of[-_ ]directors/) || lowerText.match(/motion|action:|roll call|treasurer/)) {
    docType = 'bod-meeting';
  // 2. Board Assignments: before SWCLC because assignments docs reference SWCLC as committee
  } else if (lowerFilename.match(/assign|calendar|quarter/) || lowerText.match(/committee assignments|assigned|event.*date.*time.*location/)) {
    docType = 'board-assignments';
  // 3. Membership Report
  } else if (lowerFilename.match(/membership|eom|report/) || lowerText.match(/renewals|drops|budget.*variance/)) {
    docType = 'membership-report';
  // 4. SWCLC Sign-On: coalition letters, sign-on requests (BEFORE general swclc)
  } else if (docTypeHint === 'swclc-sign-on' ||
             lowerFilename.match(/sign[-_ ]?on|coalition|position[-_ ]letter/) ||
             lowerText.match(/sign[-\s]?on\s+(letter|request|form)|coalition\s+letter|letter\s+of\s+(support|opposition)|position\s+letter|we\s+(?:support|oppose)\s+(?:AB|SB|HB)/i)) {
    docType = 'swclc-sign-on';
  // 5. SWCLC: last because other doc types may reference SWCLC
  } else if (lowerFilename.match(/swclc|legislative|southwest/) || lowerText.match(/capitol report|legislative report|bill presentation|southwest california legislative/)) {
    docType = 'swclc';
  }

  // Extract structured data
  const dollarRegex = /\$[\d,]+\.?\d*/g;
  const dollarMatches = rawText.match(dollarRegex) || [];
  const dollarAmounts = dollarMatches.map(m => {
    const matchIdx = rawText.indexOf(m);
    const start = Math.max(0, matchIdx - 80);
    const end = Math.min(rawText.length, matchIdx + m.length + 80);
    return { amount: parseFloat(m.replace(/[$,]/g, '')), context: rawText.substring(start, end).trim() };
  });

  const billRegex = /(?:SB|AB|HB)\s*\d+/gi;
  const legislation = [...new Set((rawText.match(billRegex) || []).map(b => b.toUpperCase()))];

  const actionRegex = /Action:\s*.+/gi;
  const actionItems = (rawText.match(actionRegex) || []).map(a => a.trim());

  const jimRegex = /.*(?:Toth|2nd Vice Chair).*/gi;
  const jimMentions = (rawText.match(jimRegex) || []).map(l => l.trim()).slice(0, 20);

  // Extract dates
  const dateRegex = /(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+\d{4}/gi;
  const datesFound = (rawText.match(dateRegex) || []).map(d => {
    try {
      const parsed = new Date(d);
      return parsed.toISOString().split('T')[0];
    } catch (e) { return null; }
  }).filter(Boolean);

  const meetingDate = datesFound.length > 0 ? datesFound[0] : null;

  results.push({
    json: {
      from: prepData.from || '',
      fromName: prepData.fromName || '',
      subject: prepData.subject || '',
      received_at: prepData.received_at || new Date().toISOString(),
      received_at_pst: prepData.received_at_pst || '',
      messageId: prepData.messageId || '',
      threadId: prepData.threadId || '',
      raw_text: rawText,
      doc_type: docType,
      is_scanned: false,
      filename_original: prepData.filename_original || filename,
      mime_type: prepData.mime_type || mimeType,
      page_count: rawText.split('\f').length,
      meeting_date: meetingDate,
      dates_found: datesFound,
      dollar_amounts: dollarAmounts,
      [REDACTED]: legislation,
      action_items: actionItems,
      jim_mentions: jimMentions
    },
    binary: binary
  });
}

return results;

