const items = $input.all();
const results = [];

for (let idx = 0; idx < items.length; idx++) {
  const item = items[idx];
  const gmail = item.json || {};
  const binary = item.binary || {};

  // Extract email metadata from simple:false Gmail output
  let fromAddress = '';
  let fromName = '';
  if (typeof gmail.from === 'string') {
    const m = gmail.from.match(/<?([^<>\s]+@[^<>\s]+)>?/);
    fromAddress = m ? m[1] : gmail.from;
    const nm = gmail.from.match(/^"?([^"<]+)"?\s*</);
    fromName = nm ? nm[1].trim() : '';
  } else if (gmail.from) {
    fromAddress = gmail.from.value?.[0]?.address || gmail.from.text || '';
    fromName = gmail.from.value?.[0]?.name || '';
  }
  const subject = gmail.subject || '';
  const gmailId = gmail.id || '';
  const threadId = gmail.threadId || '';
  const emailDate = gmail.date || '';

  const receivedAt = emailDate ? new Date(emailDate).toISOString() : new Date().toISOString();
  let receivedAtPst = '';
  try {
    receivedAtPst = new Date(receivedAt).toLocaleString('en-US', { timeZone: 'America/Los_Angeles' });
  } catch (e) { receivedAtPst = ''; }

  // Try to get WF1 metadata from webhook
  let webhookData = {};
  try {
    webhookData = $('Doc Processor Webhook').first().json.body || $('Doc Processor Webhook').first().json || {};
  } catch (e) { webhookData = {}; }

  // Find first PDF or DOCX binary attachment
  let pdfKey = null;
  let docxKey = null;
  let foundFilename = '';
  let foundMimeType = '';

  for (const [key, binaryData] of Object.entries(binary)) {
    const mime = (binaryData.mimeType || '').toLowerCase();
    if (mime === 'application/pdf' && !pdfKey) {
      pdfKey = key;
      foundFilename = binaryData.fileName || key;
      foundMimeType = mime;
    } else if (mime === 'application/vnd.[REDACTED].wordprocessingml.document' && !docxKey) {
      docxKey = key;
      if (!pdfKey) {
        foundFilename = binaryData.fileName || key;
        foundMimeType = mime;
      }
    }
  }

  const targetKey = pdfKey || docxKey;

  // Build new binary object with target attachment as 'data'
  const newBinary = {};
  if (targetKey && binary[targetKey]) {
    newBinary.data = binary[targetKey];
  }

  results.push({
    json: {
      from: fromAddress || webhookData.from || '',
      fromName: fromName || webhookData.fromName || '',
      subject: subject || webhookData.subject || '',
      received_at: receivedAt,
      received_at_pst: receivedAtPst || webhookData.received_at_pst || '',
      messageId: gmailId || webhookData.messageId || '',
      threadId: threadId || webhookData.threadId || '',
      filename_original: foundFilename,
      mime_type: foundMimeType,
      binary_key_used: targetKey || 'none',
      binary_count: Object.keys(binary).length,
      has_attachment: !!targetKey
    },
    binary: newBinary
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const gmail = item.json || {};

  let fromAddress = '';
  let fromName = '';
  if (typeof gmail.from === 'string') {
    const m = gmail.from.match(/<?([^<>\s]+@[^<>\s]+)>?/);
    fromAddress = m ? m[1] : gmail.from;
    const nm = gmail.from.match(/^"?([^"<]+)"?\s*</);
    fromName = nm ? nm[1].trim() : '';
  } else if (gmail.from) {
    fromAddress = gmail.from.value?.[0]?.address || gmail.from.text || '';
    fromName = gmail.from.value?.[0]?.name || '';
  }
  const subject = gmail.subject || '';
  const gmailId = gmail.id || '';
  const threadId = gmail.threadId || '';
  const emailDate = gmail.date || '';

  const receivedAt = emailDate ? new Date(emailDate).toISOString() : new Date().toISOString();
  let receivedAtPst = '';
  try {
    receivedAtPst = new Date(receivedAt).toLocaleString('en-US', { timeZone: 'America/Los_Angeles' });
  } catch (e) { receivedAtPst = ''; }

  let bodyText = '';
  if (gmail.text) bodyText = gmail.text;
  if (!bodyText && gmail.textPlain) bodyText = gmail.textPlain;

  if (!bodyText && gmail.payload) {
    const extractText = (parts) => {
      if (!parts) return '';
      for (const part of parts) {
        if (part.mimeType === 'text/plain' && part.body?.data) {
          return Buffer.from(part.body.data, 'base64').toString('utf-8');
        }
        if (part.parts) { const n = extractText(part.parts); if (n) return n; }
      }
      return '';
    };
    if (gmail.payload.body?.data) {
      bodyText = Buffer.from(gmail.payload.body.data, 'base64').toString('utf-8');
    } else if (gmail.payload.parts) {
      bodyText = extractText(gmail.payload.parts);
    }
  }

  if (!bodyText && gmail.textHtml) {
    bodyText = gmail.textHtml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  }

  // Get doc_type hint from WF1 (if available)
  let docTypeHint = '';
  try {
    docTypeHint = $('Doc Processor Webhook').first().json.body.docTypeHint || '';
  } catch (e) { /* no hint */ }

  // Classify doc_type — detect sign-on patterns (v1.4)
  let docType = 'email-communication';
  const subjectLower = subject.toLowerCase();
  const bodyLower = bodyText.toLowerCase().substring(0, 3000);
  if (docTypeHint === 'swclc-sign-on' ||
      subjectLower.match(/sign[-\s]?on|coalition\s+letter|letter\s+of\s+(support|opposition)|position\s+letter/) ||
      bodyLower.match(/sign[-\s]?on\s+(letter|request|form)|coalition\s+letter|we\s+(?:support|oppose)\s+(?:AB|SB|HB)/i)) {
    docType = 'swclc-sign-on';
  }

  const dollarRegex = /\$[\d,]+\.?\d*/g;
  const dollarMatches = bodyText.match(dollarRegex) || [];
  const dollarAmounts = dollarMatches.map(m => {
    const idx = bodyText.indexOf(m);
    const s = Math.max(0, idx - 80);
    const e = Math.min(bodyText.length, idx + m.length + 80);
    return { amount: parseFloat(m.replace(/[$,]/g, '')), context: bodyText.substring(s, e).trim() };
  });

  const billRegex = /(?:SB|AB|HB)\s*\d+/gi;
  const legislation = [...new Set((bodyText.match(billRegex) || []).map(b => b.toUpperCase()))];

  const actionRegex = /Action:\s*.+/gi;
  const actionItems = (bodyText.match(actionRegex) || []).map(a => a.trim());

  const jimRegex = /.*(?:Toth|2nd Vice Chair).*/gi;
  const jimMentions = (bodyText.match(jimRegex) || []).map(l => l.trim()).slice(0, 20);

  const dateRegex = /(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},?\s+\d{4}/gi;
  const datesFound = (bodyText.match(dateRegex) || []).map(d => {
    try { return new Date(d).toISOString().split('T')[0]; } catch (e) { return null; }
  }).filter(Boolean);
  const meetingDate = datesFound.length > 0 ? datesFound[0] : null;

  const now = new Date();
  const pstStr = now.toLocaleString('en-US', {
    timeZone: 'America/Los_Angeles',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false
  });
  const meetingDateStr = meetingDate || now.toISOString().split('T')[0];

  const metadata = {
    received_at: receivedAt,
    received_at_pst: receivedAtPst || pstStr,
    sender: fromAddress,
    email_subject: subject,
    filename_original: '(email body)',
    doc_type: docType,
    meeting_date: meetingDateStr,
    page_count: 0,
    raw_text: bodyText,
    similarity_cluster: docType,
    prior_version_path: null,
    diff_run: false,
    analysis_id: null,
    delivery_status: 'pending'
  };

  const metaFilename = meetingDateStr + '_' + docType + '_meta.json';

  results.push({
    json: {
      from: fromAddress, fromName, subject,
      received_at: receivedAt,
      received_at_pst: receivedAtPst || pstStr,
      messageId: gmailId, threadId,
      raw_text: bodyText,
      doc_type: docType,
      is_scanned: false,
      filename_original: '(email body)',
      mime_type: 'text/plain',
      page_count: 0,
      meeting_date: meetingDate,
      dates_found: datesFound,
      dollar_amounts: dollarAmounts,
      legislation_mentioned: legislation,
      action_items: actionItems,
      jim_mentions: jimMentions,
      drive_path: '',
      drive_folder_id: '[REDACTED_TOKEN]',
      metadata,
      meta_json_string: JSON.stringify(metadata, null, 2),
      meta_filename: metaFilename
    }
  });
}

return results;
